-- Unified module and employment scope tests: Docker only, always rolled back.
begin;
\ir helpers/auth-session.psql
\ir helpers/document-workspace.psql
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
create function pg_temp.workspace_suite() returns setof text language plpgsql as $$
declare org uuid:=gen_random_uuid(); actor uuid:=gen_random_uuid(); viewer uuid:=gen_random_uuid(); company uuid;
  worker uuid; second_worker uuid; employment uuid; reentry uuid; second_employment uuid;
  planilla uuid; afp uuid; boleta uuid; ingreso uuid; cese uuid; memorandum uuid;
  result jsonb; base jsonb; scope jsonb; first_payroll uuid; second_payroll uuid; event_id uuid;
  member uuid; role_id uuid; permission uuid;
begin
  insert into auth.users(id,email) values(actor,'workspace-'||actor||'@example.test'),(viewer,'workspace-'||viewer||'@example.test');
  insert into public.profiles(user_id,email,full_name,provisioning_status) select id,email,'Workspace Docker','ready' from auth.users where id in(actor,viewer);
  insert into public.organizations(id,name) values(org,'Unified document workspace');
  insert into public.organization_members(organization_id,user_id,member_type,is_admin) values(org,actor,'internal',true);
  insert into public.organization_members(organization_id,user_id,member_type) values(org,viewer,'client') returning id into member;
  insert into public.companies(organization_id,ruc,legal_name,control_start_date) values(org,'20999999663','Workspace company','2026-01-01') returning id into company;
  insert into public.workers(organization_id,company_id,identity_type,identity_number,first_names,last_names) values(org,company,'DNI','00000101','First','Worker') returning id into worker;
  insert into public.workers(organization_id,company_id,identity_type,identity_number,first_names,last_names) values(org,company,'DNI','00000102','Second','Worker') returning id into second_worker;
  insert into public.employment_periods(organization_id,company_id,worker_id,sequence_number,start_date,end_date,termination_reason) values(org,company,worker,1,'2026-01-01','2026-06-30','fin_contrato') returning id into employment;
  insert into public.employment_periods(organization_id,company_id,worker_id,sequence_number,start_date) values(org,company,worker,2,'2026-07-01') returning id into reentry;
  insert into public.employment_periods(organization_id,company_id,worker_id,sequence_number,start_date) values(org,company,second_worker,1,'2026-01-01') returning id into second_employment;
  insert into public.document_types(organization_id,module,code,name,suggested_formats) values(org,'laboral_general','laboral_planilla','Planilla','{pdf}') returning id into planilla;
  insert into public.document_types(organization_id,module,code,name,suggested_formats) values(org,'laboral_general','laboral_planilla_afp','Planilla AFP','{pdf}') returning id into afp;
  insert into public.document_types(organization_id,module,code,name,suggested_formats) values(org,'laboral_trabajador','relacion_boleta','Boleta','{pdf}') returning id into boleta;
  insert into public.document_types(organization_id,module,code,name,suggested_formats) values(org,'laboral_trabajador','ingreso_ficha','Ficha de ingreso','{pdf}') returning id into ingreso;
  insert into public.document_types(organization_id,module,code,name,suggested_formats) values(org,'laboral_trabajador','cese_liquidacion','Liquidacion','{pdf}') returning id into cese;
  insert into public.document_types(organization_id,module,code,name,suggested_formats) values(org,'laboral_trabajador','relacion_memorandum','Memorandum','{pdf}') returning id into memorandum;
  perform pg_temp.period_obligation(org,company,planilla,actor,'laboral_general','fortnightly','2026-01-01','2026-01-15','2026-01-16','First fortnight');
  perform pg_temp.period_obligation(org,company,planilla,actor,'laboral_general','fortnightly','2026-01-16','2026-01-31','2026-02-01','Second fortnight');
  perform pg_temp.period_obligation(org,company,afp,actor,'laboral_general','monthly','2026-01-01','2026-01-31','2026-02-05','Monthly AFP');
  first_payroll:=pg_temp.period_obligation(org,company,boleta,actor,'laboral_trabajador','monthly','2026-01-01','2026-01-31','2026-02-01','First period payroll',employment,'relacion');
  second_payroll:=pg_temp.period_obligation(org,company,boleta,actor,'laboral_trabajador','monthly','2026-07-01','2026-07-31','2026-08-01','Reentry payroll',reentry,'relacion');
  perform pg_temp.period_obligation(org,company,boleta,actor,'laboral_trabajador','monthly','2026-01-01','2026-01-31','2026-02-01','Other worker payroll',second_employment,'relacion');
  perform pg_temp.period_obligation(org,company,ingreso,actor,'laboral_trabajador','event','2026-01-01','2026-01-01','2026-01-05','Entry checklist',employment,'ingreso');
  perform pg_temp.period_obligation(org,company,cese,actor,'laboral_trabajador','event','2026-06-30','2026-06-30','2026-07-05','Exit checklist',employment,'cese');
  event_id:=pg_temp.period_obligation(org,company,memorandum,actor,'laboral_trabajador','event','2026-05-15','2026-05-15','2026-05-20','Event memorandum',employment,'relacion');
  perform pg_temp.authenticate(jsonb_build_object('sub',actor,'role','authenticated','session_id',gen_random_uuid())::text,true);
  perform public.h02_context();
  base:=jsonb_build_object('company_id',company,'year',2026,'month',1,'module','laboral_general');
  result:=public.h03_query(org,'document_workspace',base);
  return next extensions.is(result#>>'{data,selected_code}','laboral_planilla','Laboral general uses the same ordered document selection');
  return next extensions.is((result#>>'{data,count}')::int,2,'both fortnights remain in the selected month');
  return next extensions.is(result#>>'{data,rows,1,period_start}','2026-01-16','fortnight order follows actual dates');
  return next extensions.is(jsonb_array_length(result#>'{data,groups}'),2,'AFP remains a separate monthly document type');
  scope:=base||jsonb_build_object('module','laboral_trabajador','worker_id',worker,'employment_period_id',employment,'employment_stage','relacion','document_scope','periodic');
  result:=public.h03_query(org,'document_workspace',scope);
  return next extensions.is((result#>>'{data,count}')::int,1,'worker and employment scope isolate the payroll');
  return next extensions.is(result#>>'{data,rows,0,id}',first_payroll::text,'old employment does not mix with reentry or another worker');
  return next extensions.is((public.h03_query(org,'document_workspace',scope||'{"month":5}')#>>'{data,count}')::int,0,'monthly mode does not mix in eventual documents');
  result:=public.h03_query(org,'document_workspace',(scope-'month')||'{"document_scope":"event"}');
  return next extensions.is(result#>>'{data,rows,0,id}',event_id::text,'eventual documents remain accessible without selecting a calendar month');
  result:=public.h03_query(org,'document_workspace',(scope-'month')||'{"document_scope":"checklist","employment_stage":"ingreso"}');
  return next extensions.is(result#>>'{data,rows,0,title}','Entry checklist','Ingreso keeps its checklist instead of a monthly filter');
  result:=public.h03_query(org,'document_workspace',(scope-'month')||'{"document_scope":"checklist","employment_stage":"cese"}');
  return next extensions.is(result#>>'{data,rows,0,title}','Exit checklist','Cese keeps its own checklist and historical employment');
  result:=public.h03_query(org,'document_workspace',scope||jsonb_build_object('month',7,'employment_period_id',reentry));
  return next extensions.is(result#>>'{data,rows,0,id}',second_payroll::text,'reentry selects the new employment only');
  return next extensions.is(public.h03_query(org,'document_workspace',scope||jsonb_build_object('worker_id',second_worker))#>>'{error,code}','NOT_FOUND','foreign employment selection is rejected before reading documents');
  return next extensions.is(public.h03_query(org,'document_workspace',base||'{"document_scope":"event"}')#>>'{error,code}','VALIDATION_ERROR','event mode cannot widen scope outside an employment');
  return next extensions.is(public.h03_query(org,'document_workspace',base||'{"module":"other"}')#>>'{error,code}','VALIDATION_ERROR','unknown modules are rejected');
  insert into public.permissions(organization_id,module,action,description) values(org,'laboral_general','view','Workspace viewer') returning id into permission;
  insert into public.roles(organization_id,code,name,audience) values(org,'workspace_view','Workspace viewer','client') returning id into role_id;
  insert into public.role_permissions(organization_id,role_id,permission_id) values(org,role_id,permission);
  insert into public.access_grants(organization_id,member_id,scope,company_id,module,role_id) values(org,member,'company',company,'laboral_general',role_id);
  perform pg_temp.authenticate(jsonb_build_object('sub',viewer,'role','authenticated','session_id',gen_random_uuid())::text,true);
  perform public.h02_context();
  return next extensions.ok(public.h03_query(org,'document_workspace',base)->>'ok'='true','client can read its authorized module');
  return next extensions.is(public.h03_query(org,'document_workspace',base||'{"module":"tributario"}')#>>'{error,code}','FORBIDDEN','same company does not grant another module');
  return next extensions.is(public.h03_query(org,'document_workspace',scope)#>>'{error,code}','FORBIDDEN','laboral_general does not grant worker documents');
end $$;
select * from pg_temp.workspace_suite();
select * from extensions.finish();
rollback;
